study::OrdinaryPredefinedRecord manual(size_t group,size_t ordinal,uintptr_t id,study::Point position,double angle=0){return {group,ordinal,{id,position,{0,angle,angle},2}};}
study::ReverseRunnerFactory offset(){return [](const study::Input &input)->study::ReverseRunner{const auto program=study::offsetProgram(input);return [program](const auto &source,auto &time,auto &state){return study::ordinaryOffsetContinue(source,program,time,state);};};}
void native(const study::OrdinaryMultiPredefinedScene &scene){std::set<uintptr_t> unique;size_t count=0;for(const auto &owned:scene.boards){const auto &board=*owned;check(board.lifecycle.instances.empty()&&board.lifecycle.catalog.states.empty(),"mapped continuation retains exactly one global concrete-state table");check(board.nesting.placements.size()==board.output.placements.size(),"mapped native/output strong owner counts");for(size_t n=0;n<board.nesting.placements.size();++n){const auto &p=board.nesting.placements[n];const auto index=size_t(p->instance18);const auto &output=board.output.placements[n];check(scene.instances[index].owner08==&board.nesting&&scene.instances[index].current00.lock()==p&&scene.catalog->instances[index].placed&&scene.placementCatalog.states[index]==1,"mapped concrete state belongs to the correct actual board");check(scene.catalog->instances[index].group==output.group&&scene.catalog->instances[index].ordinal==output.ordinal,"mapped output group/ordinal matches actual remapped native instance");check(unique.insert(scene.sdkIdentities[index]).second,"unique remapped global concrete SDK ID");++count;}}check(count+scene.unplaced.size()==scene.sdkIdentities.size(),"mapped global demand conservation");boards+=scene.boards.size();placements+=count;}
void retained(const study::OrdinaryMultiPredefinedScene &old,const study::OrdinaryMultiPredefinedScene &current){check(current.boards.size()>=old.boards.size(),"all old physical board occurrences including empty ones survive");for(size_t n=0;n<old.boards.size();++n){const auto &source=*old.boards[n],&board=*current.boards[n];check(board.source.sheetIdentity==source.source.sheetIdentity,"old board occurrence order");for(size_t k=0;k<source.output.placements.size();++k){const auto &a=source.output.placements[k],&b=board.output.placements[k];const auto id=old.sdkIdentities[size_t(source.nesting.placements[k]->instance18)];check(current.sdkIdentities[size_t(board.nesting.placements[k]->instance18)]==id&&a.poseIndex==b.poseIndex&&a.x==b.x&&a.y==b.y,"SDK stable identity retains physical placement after group/ordinal changes");check(source.nesting.placements[k]!=board.nesting.placements[k]&&source.nesting.placements[k]->geometryOwner==board.nesting.placements[k]->geometryOwner,"mapped continuation owns independent placement properties and shared immutable geometry");}}}
template<class Fn>void rejects(Fn fn,int code){try{fn();throw std::runtime_error("expected mapped continuation rejection");}catch(const study::Failure &failure){check(failure.code==code,"explicit mapped continuation boundary");++cases;}}
study::Input rectangles(int quantity,double width=12,double height=8){study::Input input;input.width=width;input.height=height;input.pitch=.5;input.parts={{{{0,0},{3,0},{3,2},{0,2}},{},{{0,false}},quantity}};return input;}
